import{_ as a,o as l,c as o,a2 as i}from"./chunks/framework.DSoq407f.js";const p=JSON.parse('{"title":"我的订阅","description":"","frontmatter":{},"headers":[],"relativePath":"console/subscriptions.md","filePath":"console/subscriptions.md","lastUpdated":1786543008000}'),e={name:"console/subscriptions.md"};function r(s,t,n,d,c,h){return l(),o("div",null,[...t[0]||(t[0]=[i('<h1 id="我的订阅" tabindex="-1">我的订阅 <a class="header-anchor" href="#我的订阅" aria-label="Permalink to &quot;我的订阅&quot;">​</a></h1><blockquote><p><strong>你会学到</strong>：查看订阅状态、购买 / 续订套餐、用卡密兑换。</p></blockquote><h2 id="查看订阅" tabindex="-1">查看订阅 <a class="header-anchor" href="#查看订阅" aria-label="Permalink to &quot;查看订阅&quot;">​</a></h2><p>显示你当前的订阅：</p><ul><li>套餐名称、计费模式（月 / 年 / 永久）</li><li>到期时间、剩余天数</li><li>资源配额（机器人数、插件数）及已用量</li><li>套餐包含的插件、可用平台</li></ul><h2 id="购买-升级套餐" tabindex="-1">购买 / 升级套餐 <a class="header-anchor" href="#购买-升级套餐" aria-label="Permalink to &quot;购买 / 升级套餐&quot;">​</a></h2><p>在套餐列表选择适合的套餐购买：</p><ul><li>用<a href="./account">账户余额</a>支付。</li><li>升级套餐：补差价升级到更高套餐，立即获得更高配额。</li><li>购买后订阅立即生效。</li></ul><div class="tip custom-block"><p class="custom-block-title">永久套餐</p><p>永久套餐一次购买长期有效，适合长期使用者。月 / 年付则需到期前续费。</p></div><h2 id="续费" tabindex="-1">续费 <a class="header-anchor" href="#续费" aria-label="Permalink to &quot;续费&quot;">​</a></h2><p>订阅快到期时会提醒。续费可：</p><ul><li>手动续费：在「我的订阅」里点续费。</li><li>续费后到期时间顺延。</li></ul><div class="warning custom-block"><p class="custom-block-title">过期降级</p><p>订阅过期后，资源会<strong>降级</strong>（机器人停用、插件停用），但<strong>数据不删除</strong>。续费后立即恢复，历史配置和插件数据都在。</p></div><h2 id="卡密兑换" tabindex="-1">卡密兑换 <a class="header-anchor" href="#卡密兑换" aria-label="Permalink to &quot;卡密兑换&quot;">​</a></h2><p>有卡密可在「卡密兑换」里使用：</p><table tabindex="0"><thead><tr><th>卡密类型</th><th>兑换</th></tr></thead><tbody><tr><td>套餐卡</td><td>获得一个订阅套餐</td></tr><tr><td>余额卡</td><td>充值到账户余额</td></tr><tr><td>插件卡</td><td>获得某个付费插件</td></tr></tbody></table><p>输入卡密兑换即可。</p><h2 id="配额说明" tabindex="-1">配额说明 <a class="header-anchor" href="#配额说明" aria-label="Permalink to &quot;配额说明&quot;">​</a></h2><p>你的套餐决定：</p><ul><li>可创建的<strong>机器人数量</strong>上限。</li><li>可安装的<strong>插件数量</strong>上限（部分套餐按&quot;每机器人&quot;或&quot;共享&quot;计算）。</li><li>可用的<strong>平台适配器</strong>（高级套餐支持更多平台）。</li><li><strong>包含的插件</strong>（套餐内免费使用）。</li></ul><p>配额用完需升级套餐，或停用 / 删除不需要的资源。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>充值买套餐 → <a href="./account">账户与充值</a></li><li>配额用来建机器人 → <a href="./bots">机器人管理</a></li></ul>',23)])])}const b=a(e,[["render",r]]);export{p as __pageData,b as default};
